// C005 Invariant: Definitions stable within document
// Test: Each defined term is used consistently (no contradictory definitions)
#[test]
#[allow(unused)]
fn definitions_consistent() {
    // Manual review required — term consistency is a documentation quality attribute.
    // Automated grep: each term appears in §3 and is used in other sections without contradiction.
    let spec = std::fs::read_to_string("specs/P0-1.md").unwrap();
    // Verify each term appears at least twice (once in glossary, once in another section)
    let terms = ["Client", "Account", "Call", "Media Session", "Source", "Chunk Pair", "Raw SIP Event"];
    for term in &terms {
        let count = spec.matches(term).count();
        assert!(count >= 2, "Term '{}' must appear in glossary and at least one other section (found {} occurrences)", term, count);
    }
}

