#[test]
fn test_license_header_in_files() {
    // Verify each .rs file starts with the license header
    let src_dir = std::path::Path::new("src");
    let mut violations = Vec::new();

    fn check_dir(dir: &std::path::Path, violations: &mut Vec<String>) {
        for entry in std::fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if path.is_dir() {
                check_dir(&path, violations);
            } else if path.extension().map_or(false, |e| e == "rs") {
                let content = std::fs::read_to_string(&path).unwrap();
                let has_license = content.contains("SPDX-License-Identifier") 
                    || content.contains("dual-licensed");
                if !has_license && !content.starts_with("//!") {
                    violations.push(path.to_string_lossy().to_string());
                }
            }
        }
    }

    check_dir(src_dir, &mut violations);
    assert!(violations.is_empty(), "Files without license header: {:?}", violations);
}
