use std::time::Duration;
use tokio::time::{pause, timeout};

pause(); // deterministic time
let (sender, mut handle) = tap_channel(1, AudioTapMode::Lossless);
let (a, b) = (synthetic_pair(1), synthetic_pair(2));
assert_eq!(sender.push(a.clone()).await, None); // accepted
let push_b = tokio::spawn(async move { sender.push(b.clone()).await });
// channel full -> push(b) must NOT complete (backpressure)
assert!(timeout(Duration::ZERO, &mut push_b).await.is_err());
assert_eq!(handle.recv().await, Some(a));        // drain a
let dropped = push_b.await.unwrap();
assert_eq!(dropped, None);                        // no drop reported
assert_eq!(handle.recv().await, Some(b));         // b delivered intact
