  #[test]
  fn transport_type_removed_from_source_tree() {
      let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
      let src_dir = manifest_dir.join("src");
      let mut violations = Vec::new();
      for entry in std::fs::read_dir(&src_dir).unwrap() {
          let entry = entry.unwrap();
          if !entry.path().extension().map_or(false, |e| e == "rs") { continue; }
          let text = std::fs::read_to_string(entry.path()).unwrap();
          for (idx, line) in text.lines().enumerate() {
              let stripped = line.trim_start();
              if stripped.starts_with("//") { continue; }
              if stripped.contains("TransportType") { violations.push((entry.path(), idx + 1, line.to_string())); }
          }
      }
      assert!(violations.is_empty(), "TransportType still present: {violations:?}");
  }
