// tests/verify_unsafe_isolation.rs
#[test]
fn unsafe_isolated_to_ffi() {
    let src = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
    for dir in ["runtime", "config"] {
        let hits = scan_unsafe(&src.join(dir));
        assert!(hits.is_empty(), "unsafe found under src/{dir}: {hits:?}");
    }
    let client = std::fs::read_to_string(src.join("client.rs")).unwrap();
    assert!(!contains_unsafe(&client), "unsafe found in src/client.rs");
}
fn scan_unsafe(dir: &std::path::Path) -> Vec<String> {
    let mut out = Vec::new();
    for entry in std::fs::read_dir(dir).unwrap().flatten() {
        let p = entry.path();
        if p.is_dir() { out.extend(scan_unsafe(&p)); continue; }
        if p.extension().and_then(|e| e.to_str()) != Some("rs") { continue; }
        let text = std::fs::read_to_string(&p).unwrap();
        if contains_unsafe(&text) { out.push(p.display().to_string()); }
    }
    out
}
fn contains_unsafe(text: &str) -> bool {
    text.lines().any(|l| l.contains("unsafe") && !l.trim_start().starts_with("//"))
}
